SELECT ts, ROW_NUMBER() OVER (ORDER BY ___) AS n
FROM audit_log
WHERE login = ___ AND ts > ___;

WITH last AS (
  SELECT from_msisdn, to_msisdn, ts, created_at, kind, status,
         ROW_NUMBER() OVER (PARTITION BY ___ ORDER BY ___) AS rn
  FROM messenger_events
)
SELECT * FROM last WHERE rn = 1 ORDER BY ts DESC;

WITH nights AS (
  SELECT date(ts, '-8 hours') AS night, COUNT(*) AS actions
  FROM audit_log WHERE ___ GROUP BY night
),
ranked AS (
  SELECT night, actions, ___ OVER (ORDER BY actions DESC) AS place FROM nights
)
SELECT * FROM ranked WHERE place <= 3;
